import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import { Card } from "primereact/card";
import { Button } from "primereact/button";
import { InputText } from "primereact/inputtext";
import { Dropdown } from "primereact/dropdown";
import { Calendar } from "primereact/calendar";
import { Toast } from "primereact/toast";

const ManageClinicProfile = ({ clinicId }) => {
  const [clinic, setClinic] = useState(null);
  const [editing, setEditing] = useState(false);
  const toast = useRef(null);

  useEffect(() => {
    fetchClinic();
  }, []);

  const fetchClinic = async () => {
    try {
      const response = await axios.get(`http://localhost:5000/api/clinics/${clinicId}`);
      setClinic(response.data);
    } catch (error) {
      console.error("Error fetching clinic:", error);
    }
  };

  const handleSave = async () => {
    try {
      await axios.put(`http://localhost:5000/api/clinics/${clinicId}`, clinic);
      showToast("success", "Updated", "Clinic details updated successfully.");
      setEditing(false);
    } catch (error) {
      showToast("error", "Error", "Failed to update clinic.");
    }
  };

  const showToast = (severity, summary, detail) => {
    toast.current.show({ severity, summary, detail, life: 3000 });
  };

  if (!clinic) return <p>Loading...</p>;

  return (
    <div className="p-6">
      <Toast ref={toast} />
      <Card className="shadow-md p-4">
        <div className="flex flex-col md:flex-row items-center">
          {/* Clinic Logo */}
          <div className="w-32 h-32">
            <img src={clinic.logo || "https://via.placeholder.com/100"} alt="Clinic Logo" className="rounded-full w-full h-full object-cover" />
          </div>

          {/* Clinic Details */}
          <div className="ml-6 flex-1">
            <h2 className="text-2xl font-bold">{clinic.name}</h2>
            <p className="text-gray-600">{clinic.address}</p>
            <p className="text-gray-600">📞 {clinic.contact_number}</p>

            {/* Status */}
            <div className="mt-2">
              <span className={`px-3 py-1 text-white rounded-full text-sm ${clinic.status === "Active" ? "bg-green-500" : "bg-red-500"}`}>
                {clinic.status}
              </span>
            </div>
          </div>
        </div>

        {/* Editable Fields */}
        {editing ? (
          <div className="mt-6">
            <label>Clinic Name</label>
            <InputText value={clinic.name} onChange={(e) => setClinic({ ...clinic, name: e.target.value })} className="w-full mb-2" />

            <label>Address</label>
            <InputText value={clinic.address} onChange={(e) => setClinic({ ...clinic, address: e.target.value })} className="w-full mb-2" />

            <label>Contact Number</label>
            <InputText value={clinic.contact_number} onChange={(e) => setClinic({ ...clinic, contact_number: e.target.value })} className="w-full mb-2" />

            <label>Status</label>
            <Dropdown
              value={clinic.status}
              options={[
                { label: "Active", value: "Active" },
                { label: "Inactive", value: "Inactive" },
              ]}
              onChange={(e) => setClinic({ ...clinic, status: e.value })}
              className="w-full mb-2"
            />

            <label>Days Open</label>
            <InputText value={clinic.days} onChange={(e) => setClinic({ ...clinic, days: e.target.value })} className="w-full mb-2" />

            <label>Open Time</label>
            <Calendar
              value={clinic.open_time ? new Date(`1970-01-01T${clinic.open_time}`) : null}
              onChange={(e) => setClinic({ ...clinic, open_time: e.value.toTimeString().split(" ")[0] })}
              timeOnly
              className="w-full mb-2"
            />

            <label>Close Time</label>
            <Calendar
              value={clinic.close_time ? new Date(`1970-01-01T${clinic.close_time}`) : null}
              onChange={(e) => setClinic({ ...clinic, close_time: e.value.toTimeString().split(" ")[0] })}
              timeOnly
              className="w-full mb-2"
            />

            <label>Image URL</label>
            <InputText value={clinic.image} onChange={(e) => setClinic({ ...clinic, image: e.target.value })} className="w-full mb-2" />

            <label>Logo URL</label>
            <InputText value={clinic.logo} onChange={(e) => setClinic({ ...clinic, logo: e.target.value })} className="w-full mb-2" />

            <div className="mt-4">
              <Button label="Cancel" className="p-button-secondary mr-2" onClick={() => setEditing(false)} />
              <Button label="Save Changes" className="p-button-primary" onClick={handleSave} />
            </div>
          </div>
        ) : (
          <div className="mt-6">
            <p><strong>Days Open:</strong> {clinic.days}</p>
            <p><strong>Open Time:</strong> {clinic.open_time}</p>
            <p><strong>Close Time:</strong> {clinic.close_time}</p>

            <div className="mt-4">
              <Button label="Edit Clinic" icon="pi pi-pencil" className="p-button-warning" onClick={() => setEditing(true)} />
            </div>
          </div>
        )}
      </Card>
    </div>
  );
};

export default ManageClinicProfile;
